    "question": "Uyluğa ve bacağa aynı anda fleksiyon yaptıran, ayrıca uyluğa abduksiyon ve dış rotasyon yaptırarak 'terzi oturuşu' pozisyonu sağlayan kas aşağıdakilerden hangisidir?",
