    "question": "Tam ekstansiyondaki diz ekleminin fleksiyonunu başlatırken femur'u dış rotasyona (veya serbest tibia'yı iç rotasyona) uğratarak dizin kilitlenmesini çözen kas aşağıdakilerden hangisidir?",
